const monthly =
	Number(get(rate, 'amount', 0)) +
	sum(Object.values(get(ctx.entry, 'terms.allowances', {})).map((a) => Number(get(a, 'amount', 0))));
const worksite = get(ctx.entry, 'employee_extension_data.worksite_kbli', '');
const facts = get(entity, 'entity_extension_data', {});
const job = get(ctx.entry, 'employee_extension_data.umsp_job_category', '');
const bySector = ctx.lookup.by_sector;
const star = Number(get(facts, 'umsp_hotel_star', 0));
const conditionMatches = (row) => {
    const condition = get(row, 'condition', '');
    if (condition === '') return true;
    if (condition === 'HOTEL_STAR_3') return star === 3;
    if (condition === 'HOTEL_STAR_4') return star === 4;
    if (condition === 'HOTEL_STAR_5') return star === 5;
    if (condition === 'HOTEL_4_5') return star >= ctx.lookup.hotel_stars_4_5_min;
    if (condition === 'HOTEL_3_5') return star >= ctx.lookup.hotel_stars_3_5_min;
    if (condition === 'BANK_PRIVATE_FOREX') return get(facts, 'umsp_bank_category', '') === 'PRIVATE_CONVENTIONAL_FOREX';
    if (condition === 'BANK_SYARIAH_FOREX') return get(facts, 'umsp_bank_category', '') === 'SYARIAH_FOREX';
    if (condition === 'RAYON_VISCOSE') return get(facts, 'umsp_rayon_viscose', false) === true;
    if (condition === 'EXPORT') return get(facts, 'umsp_export_oriented', false) === true;
    if (condition === 'ASSETS_1T') return get(facts, 'umsp_assets_over_1_trillion', false) === true;
    if (condition === 'ASTRA') return get(facts, 'umsp_astra_group', false) === true;
    if (condition === 'FREEPORT_AREA') return get(facts, 'umsp_freeport_area', false) === true;
    if (condition === 'BUS_DRIVER_MECHANIC') return job === 'BUS_DRIVER_MECHANIC';
    if (condition === 'CLASS_A_HOSPITAL_CARE') return get(facts, 'umsp_class_a_private_hospital', false) === true && ['NURSING_MIDWIFERY', 'MEDICAL_SUPPORT'].includes(job);
    return false;
};
const covered = (key) => region === key || region.startsWith(key + '/');
const underpaid = (row) => {
    if (!worksite.startsWith(get(row, 'kbli', ''))) return false;
    if (!conditionMatches(row)) return false;
    return monthly < Number(get(row, 'monthly', 0));
};
return !Object.keys(bySector).some((key) => covered(key) && bySector[key].some(underpaid));

